PRAGMA foreign_keys = ON;
CREATE TABLE entries(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('service','case')), slug TEXT NOT NULL, head TEXT REFERENCES revisions(id) DEFERRABLE INITIALLY DEFERRED, UNIQUE(kind,slug));
CREATE TABLE revisions(id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entries(id), parent_id TEXT REFERENCES revisions(id), content TEXT NOT NULL CHECK(json_valid(content)), created_at INTEGER NOT NULL, UNIQUE(entry_id,id));
CREATE INDEX revisions_entry ON revisions(entry_id,created_at);
CREATE TRIGGER revisions_immutable_update BEFORE UPDATE ON revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER revisions_immutable_delete BEFORE DELETE ON revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER head_same_entry BEFORE UPDATE OF head ON entries WHEN NEW.head IS NOT NULL AND NOT EXISTS(SELECT 1 FROM revisions WHERE id=NEW.head AND entry_id=NEW.id) BEGIN SELECT RAISE(ABORT,'foreign revision'); END;
CREATE TABLE media(id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, alt TEXT NOT NULL);
INSERT INTO media VALUES('social-card','/social-card.png','and_mad: desarrollo web y contenido');
CREATE TABLE evidence(revision_id TEXT NOT NULL REFERENCES revisions(id), id TEXT NOT NULL, label TEXT NOT NULL, url TEXT, image_id TEXT REFERENCES media(id), PRIMARY KEY(revision_id,id));
CREATE TABLE imports(fingerprint TEXT PRIMARY KEY, resource_id TEXT NOT NULL, source_label TEXT NOT NULL, revision_id TEXT NOT NULL REFERENCES revisions(id), created_at INTEGER NOT NULL);
CREATE TABLE releases(id TEXT PRIMARY KEY, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), source_revision TEXT NOT NULL CHECK(length(source_revision)=40), state TEXT NOT NULL CHECK(state IN ('approved','deploying','published','failed')), attempt_id TEXT, created_at INTEGER NOT NULL, deployed_at INTEGER);
CREATE UNIQUE INDEX one_deploy ON releases(state) WHERE state='deploying';
CREATE TRIGGER snapshot_immutable BEFORE UPDATE OF snapshot ON releases BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER source_immutable BEFORE UPDATE OF source_revision ON releases BEGIN SELECT RAISE(ABORT,'immutable source'); END;
CREATE TABLE release_revisions(release_id TEXT NOT NULL REFERENCES releases(id), revision_id TEXT NOT NULL REFERENCES revisions(id), PRIMARY KEY(release_id,revision_id));
CREATE TABLE deployments(id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES releases(id), state TEXT NOT NULL CHECK(state IN ('deploying','published','failed')), created_at INTEGER NOT NULL, finished_at INTEGER);
CREATE TABLE audit(id TEXT PRIMARY KEY, actor TEXT NOT NULL, operation TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX audit_time ON audit(created_at);
CREATE TABLE credentials(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, resources TEXT NOT NULL CHECK(json_valid(resources)), revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)), last_seen INTEGER);
CREATE TABLE requests(id TEXT PRIMARY KEY, credential_id TEXT NOT NULL REFERENCES credentials(id), query TEXT NOT NULL CHECK(json_valid(query)), state TEXT NOT NULL CHECK(state IN('pending','claimed','done')), expires_at INTEGER NOT NULL, lease TEXT UNIQUE, lease_until INTEGER, result TEXT, result_ok INTEGER CHECK(result_ok IN(0,1)), result_expires INTEGER, CHECK(result IS NULL OR result_expires IS NOT NULL));
CREATE INDEX requests_pending ON requests(credential_id,state,expires_at);
CREATE INDEX requests_expiry ON requests(result_expires,expires_at);
